        [TEST("PragueSky", "ModelIsTheAuthorsOnTheFullDataset")]
        public static void ModelIsTheAuthorsOnTheFullDataset()
        {
            string filename = Dataset("PragueSkyModelDatasetFull.dat");
            if (filename != null)
            {
                Compare(filename, ReferenceFull, true);
            }
        }

        // Datasets put into one file: an observer on the ground gets the dataset with the most channels of the film, one
        // above the ground the dataset that has altitudes, each exactly as from its own file; the reference implementation
        // would read the first
        [TEST("PragueSky", "CombineKeepsTheDatasets")]
        public static void CombineKeepsTheDatasets()
        {
            string wide = Dataset("PragueSkyModelDatasetSWIR.dat"), ground = Dataset("PragueSkyModelDatasetGround.dat");
            if (wide == null || ground == null)
            {
                return;
            }
            string full = Dataset("PragueSkyModelDatasetFull.dat");
            string trimmed = Path.Combine(Path.GetTempPath(), "prague_ground14_test.dat"), combined = Path.Combine(Path.GetTempPath(), "prague_combined_test.dat");
            PragueSkyModel.Trim(wide, trimmed, 280, 839);
            // (a dataset without polarisation can only be the last)
            bool refused = false;
            try
            {
                PragueSkyModel.Combine(new string[] { ground, trimmed }, combined);
            }
            catch (ArgumentException)
            {
                refused = true;
            }
            EXPECT_TRUE(refused);
            string first = full != null ? full : ground;
            if (full != null)
            {
                PragueSkyModel.Combine(new string[] { full, trimmed }, combined);
            }
            else
            {
                PragueSkyModel.Combine(new string[] { trimmed, ground }, combined);
            }
            EXPECT_EQ(new FileInfo(first).Length + new FileInfo(trimmed).Length, new FileInfo(combined).Length);
            EXPECT_EQ(2, PragueSkyModel.Describe(combined).Length);
            Spectrum albedo = new ConstantSpectrum(0.4f);
            RNG rng = new RNG(43);
            foreach (double altitude in new double[] { 0, 2700 })
            {
                if (altitude > 0 && full == null)
                {
                    // (only the ground is in the file)
                    bool thrown = false;
                    try
                    {
                        PragueSkyModel none = new PragueSkyModel(combined, 0.5, 47, albedo, altitude);
                    }
                    catch (InvalidDataException)
                    {
                        thrown = true;
                    }
                    EXPECT_TRUE(thrown);
                    continue;
                }
                PragueSkyModel alone = new PragueSkyModel(altitude > 0 ? full : trimmed, 0.5, 47, albedo, altitude);
                PragueSkyModel both = new PragueSkyModel(combined, 0.5, 47, albedo, altitude);
                EXPECT_EQ(altitude > 0 ? 11 : 14, both.Channels);
                EXPECT_EQ(altitude > 0 ? 320.0 : 280.0, both.ChannelStart);
                for (int i = 0; i < 400; ++i)
                {
                    Vector3f w = altitude > 0 ? SampleUniformSphere(new Point2f(rng.Uniform<Float>(), rng.Uniform<Float>()))
                                              : SampleUniformHemisphere(new Point2f(rng.Uniform<Float>(), rng.Uniform<Float>()));
                    if (i % 4 == 0)
                    {
                        w = new Vector3f((Float)Math.Cos(0.5), 0, (Float)Math.Sin(0.5));
                    }
                    PragueSkyModel.Angles a = alone.ComputeAngles(w.x, w.y, w.z), b = both.ComputeAngles(w.x, w.y, w.z);
                    double wavelength = Lerp(rng.Uniform<Float>(), 300f, 900f);
                    EXPECT_EQ(alone.SkyRadiance(a, wavelength), both.SkyRadiance(b, wavelength));
                    EXPECT_EQ(alone.Polarisation(a, wavelength), both.Polarisation(b, wavelength));
                    EXPECT_EQ(alone.Transmittance(a, wavelength, 30000), both.Transmittance(b, wavelength, 30000));
                    EXPECT_EQ(alone.SunRadiance(a, wavelength), both.SunRadiance(b, wavelength));
                }
            }
            File.Delete(trimmed);
            File.Delete(combined);
        }

        // The light of an observer above the ground: light from every direction, found by its own samples as by uniform
        // directions, and what the model gives
        [TEST("PragueSky", "LightAloft")]
        public static void LightAloft()
        {
            string filename = Dataset("PragueSkyModelDatasetFull.dat");
            if (filename == null)
            {
                return;
            }
            foreach (double altitude in new double[] { 800, 9000 })
            {
                foreach (bool sun in new bool[] { false, true })
                {
                    double elevationDegrees = 21, visibility = 70;
                    double elevation = elevationDegrees * Math.PI / 180;
                    Vector3f zenith = Normalize(new Vector3f(0.2f, -0.3f, 1));
                    Vector3f side = Normalize(Cross(zenith, new Vector3f(1, 0, 0)));
                    Vector3f toSun = Normalize((Float)Math.Sin(elevation) * zenith + (Float)Math.Cos(elevation) * side);
                    PragueSkyLight light = new PragueSkyLight(zenith, toSun, filename, visibility, new ConstantSpectrum(0.35f), 1, sun, false, false, altitude);
                    light.Preprocess(new Bounds3f(new Point3f(-1, -1, -1), new Point3f(1, 1, 1)));
                    PragueSkyModel model = new PragueSkyModel(filename, elevation, visibility, new ConstantSpectrum(0.35f), altitude);
                    Vector3f x = Normalize(toSun - Dot(toSun, zenith) * zenith), y = Cross(zenith, x);
                    LightSampleContext ctx = new LightSampleContext(new Point3fi(new Point3f(0, 0, 0)), new Normal3f(0, 0, 0), new Normal3f(0, 0, 0));
                    SampledWavelengths lambda = SampledWavelengths.SampleVisible(0.31f);
                    RNG rng = new RNG(37);
                    int count = 200000, below = 0;
                    double sphere = 0, sphereSquares = 0, own = 0, ownSquares = 0, uniform = 0, uniformSquares = 0;
                    for (int i = 0; i < count; ++i)
                    {
                        pstd.optional<LightLiSample> sample = light.SampleLi(ctx, new Point2f(rng.Uniform<Float>(), rng.Uniform<Float>()), lambda);
                        if ((bool)sample)
                        {
                            LightLiSample ls = sample.value();
                            EXPECT_NEAR(1.0, light.PDF_Li(ctx, ls.wi) / ls.pdf, 1e-4);
                            SampledSpectrum seen = light.Le(new Ray(new Point3f(0, 0, 0), ls.wi), lambda);
                            EXPECT_NEAR(1.0, seen[0] / ls.L[0], 5e-3);
                            double v = ls.L[0] / ls.pdf;
                            own += v;
                            ownSquares += v * v;
                            double s = 1.0 / ls.pdf;
                            sphere += s;
                            sphereSquares += s * s;
                            below += Dot(ls.wi, zenith) < 0 ? 1 : 0;
                        }
                        Vector3f w = SampleUniformSphere(new Point2f(rng.Uniform<Float>(), rng.Uniform<Float>()));
                        double radiance = light.Le(new Ray(new Point3f(0, 0, 0), w), lambda)[0];
                        PragueSkyModel.Angles angles = model.ComputeAngles(Dot(w, x), Dot(w, y), Dot(w, zenith));
                        if (angles.gamma > 2 * PragueSkyModel.SunRadius)
                        {
                            EXPECT_NEAR(1.0, (radiance + 1e-12) / (model.SkyRadiance(angles, lambda[0]) + 1e-12), 2e-3);
                        }
                        uniform += radiance * 4 * Math.PI;
                        uniformSquares += radiance * radiance * 16 * Math.PI * Math.PI;
                    }
                    own /= count;
                    uniform /= count;
                    sphere /= count;
                    double ownError = Math.Sqrt(Math.Max(0.0, ownSquares / count - own * own) / count);
                    double uniformError = Math.Sqrt(Math.Max(0.0, uniformSquares / count - uniform * uniform) / count);
                    double sphereError = Math.Sqrt(Math.Max(0.0, sphereSquares / count - sphere * sphere) / count);
                    Console.WriteLine("altitude " + altitude + " m, sun " + sun + ": by the light's samples " + own + " +- " + ownError + ", by uniform directions " +
                                      uniform + " +- " + uniformError + "; the sphere " + sphere + " +- " + sphereError + "; below the horizon " + below);
                    if (!sun)
                    {
                        EXPECT_LT(Math.Abs(own - uniform), 4 * Math.Sqrt(ownError * ownError + uniformError * uniformError));
                    }
                    EXPECT_LT(Math.Abs(sphere - 4 * Math.PI), 4 * sphereError + 1e-3);
                    EXPECT_GT(below, count / 20);
                    EXPECT_LT(ownError, 0.02 * own);
                }
            }
        }

        // A dataset cut to the channels of the film: in those channels everything is what the whole dataset gives, outside
        // them there is nothing, and the file is the smaller by the channels that were left out
        [TEST("PragueSky", "TrimKeepsTheChannels")]
        public static void TrimKeepsTheChannels()
        {
            string filename = Dataset("PragueSkyModelDatasetSWIR.dat");
            if (filename == null)
            {
                return;
            }
            string trimmed = Path.Combine(Path.GetTempPath(), "prague_trimmed_test.dat");
            PragueSkyModel.Trim(filename, trimmed, 360, 830);
            Console.WriteLine("trimmed to 360..830 nm: " + new FileInfo(trimmed).Length + " bytes of " + new FileInfo(filename).Length);
            Spectrum albedo = new ConstantSpectrum(0.4f);
            RNG rng = new RNG(41);
            foreach (double elevationDegrees in new double[] { -2, 4, 33, 71 })
            {
                PragueSkyModel whole = new PragueSkyModel(filename, elevationDegrees * Math.PI / 180, 47, albedo);
                PragueSkyModel cut = new PragueSkyModel(trimmed, elevationDegrees * Math.PI / 180, 47, albedo);
                EXPECT_EQ(12, cut.Channels);
                EXPECT_EQ(360.0, cut.ChannelStart);
                EXPECT_TRUE(cut.HasPolarisation);
                for (int i = 0; i < 400; ++i)
                {
                    Vector3f w = SampleUniformHemisphere(new Point2f(rng.Uniform<Float>(), rng.Uniform<Float>()));
                    if (i % 4 == 0)
                    {
                        // (toward the sun)
                        double e = Math.Max(elevationDegrees * Math.PI / 180, 0.001);
                        w = new Vector3f((Float)Math.Cos(e), 0, (Float)Math.Sin(e));
                    }
                    PragueSkyModel.Angles a = whole.ComputeAngles(w.x, w.y, w.z), b = cut.ComputeAngles(w.x, w.y, w.z);
                    double wavelength = Lerp(rng.Uniform<Float>(), 300f, 900f);
                    bool inside = wavelength >= 360 && wavelength < 840;
                    EXPECT_EQ(inside ? whole.SkyRadiance(a, wavelength) : 0, cut.SkyRadiance(b, wavelength));
                    EXPECT_EQ(inside ? whole.Polarisation(a, wavelength) : 0, cut.Polarisation(b, wavelength));
                    EXPECT_EQ(inside ? whole.Transmittance(a, wavelength, 30000) : 0, cut.Transmittance(b, wavelength, 30000));
                    EXPECT_EQ(inside ? whole.SunRadiance(a, wavelength) : 0, cut.SunRadiance(b, wavelength));
                }
            }
            File.Delete(trimmed);
        }

        private static PragueSkyLight Sky(string filename, bool sun, bool ground, double elevationDegrees, double visibility, bool polarised, out Vector3f zenith,
                                          out Vector3f toSun)
        {
            double elevation = elevationDegrees * Math.PI / 180;
            zenith = Normalize(new Vector3f(0.2f, -0.3f, 1));
            Vector3f side = Normalize(Cross(zenith, new Vector3f(1, 0, 0)));
            toSun = Normalize((Float)Math.Sin(elevation) * zenith + (Float)Math.Cos(elevation) * side);
            PragueSkyLight light = new PragueSkyLight(zenith, toSun, filename, visibility, new ConstantSpectrum(0.35f), 1, sun, ground, polarised);
            light.Preprocess(new Bounds3f(new Point3f(-1, -1, -1), new Point3f(1, 1, 1)));
            return light;
        }

        // The light: the density that is given is that of the samples, the radiance of a sample is that of a ray in its
        // direction and that of the model, and the light over the sphere by the samples of the light is the light by uniform
        // directions; with a sun high, low and below the horizon
        [TEST("PragueSky", "LightSamplesWhatItEmits")]
        public static void LightSamplesWhatItEmits()
        {
            foreach (string name in new string[] { "PragueSkyModelDatasetSWIR.dat", "PragueSkyModelDatasetGround.dat" })
            {
                string filename = Dataset(name);
                if (filename == null)
                {
                    continue;
                }
                foreach (double elevationDegrees in new double[] { 41, 3, -3 })
                {
                    foreach (bool sun in new bool[] { false, true })
                    {
                        foreach (bool ground in new bool[] { false, true })
                        {
                            double visibility = 55;
                            PragueSkyLight light = Sky(filename, sun, ground, elevationDegrees, visibility, false, out Vector3f zenith, out Vector3f toSun);
                            PragueSkyModel model = new PragueSkyModel(filename, elevationDegrees * Math.PI / 180, visibility, new ConstantSpectrum(0.35f));
                            Vector3f x = Normalize(toSun - Dot(toSun, zenith) * zenith), y = Cross(zenith, x);
                            LightSampleContext ctx = new LightSampleContext(new Point3fi(new Point3f(0, 0, 0)), new Normal3f(0, 0, 0), new Normal3f(0, 0, 0));
                            SampledWavelengths lambda = SampledWavelengths.SampleVisible(0.31f);
                            RNG rng = new RNG(31);
                            int count = 200000;
                            double sphere = 0, sphereSquares = 0, own = 0, ownSquares = 0, uniform = 0, uniformSquares = 0;
                            for (int i = 0; i < count; ++i)
                            {
                                pstd.optional<LightLiSample> sample = light.SampleLi(ctx, new Point2f(rng.Uniform<Float>(), rng.Uniform<Float>()), lambda);
                                if ((bool)sample)
                                {
                                    LightLiSample ls = sample.value();
                                    EXPECT_NEAR(1.0, light.PDF_Li(ctx, ls.wi) / ls.pdf, 1e-4);
                                    SampledSpectrum seen = light.Le(new Ray(new Point3f(0, 0, 0), ls.wi), lambda);
                                    EXPECT_NEAR(1.0, seen[0] / ls.L[0], 5e-3);
                                    double v = ls.L[0] / ls.pdf;
                                    own += v;
                                    ownSquares += v * v;
                                    double s = 1.0 / ls.pdf;
                                    sphere += s;
                                    sphereSquares += s * s;
                                }
                                Vector3f w = SampleUniformSphere(new Point2f(rng.Uniform<Float>(), rng.Uniform<Float>()));
                                Float pdf = light.PDF_Li(ctx, w);
                                double radiance = light.Le(new Ray(new Point3f(0, 0, 0), w), lambda)[0];
                                if (radiance > 0)
                                {
                                    EXPECT_GT(pdf, 0);
                                }
                                if (Dot(w, zenith) > 0.01f)
                                {
                                    // (the sky away from the disc is the sky of the model)
                                    PragueSkyModel.Angles angles = model.ComputeAngles(Dot(w, x), Dot(w, y), Dot(w, zenith));
                                    if (angles.gamma > 2 * PragueSkyModel.SunRadius)
                                    {
                                        EXPECT_NEAR(1.0, (radiance + 1e-12) / (model.SkyRadiance(angles, lambda[0]) + 1e-12), 2e-3);
                                    }
                                }
                                uniform += radiance * 4 * Math.PI;
                                uniformSquares += radiance * radiance * 16 * Math.PI * Math.PI;
                            }
                            own /= count;
                            uniform /= count;
                            sphere /= count;
                            double ownError = Math.Sqrt(Math.Max(0.0, ownSquares / count - own * own) / count);
                            double uniformError = Math.Sqrt(Math.Max(0.0, uniformSquares / count - uniform * uniform) / count);
                            double sphereError = Math.Sqrt(Math.Max(0.0, sphereSquares / count - sphere * sphere) / count);
                            Console.WriteLine(name + ", " + elevationDegrees + " deg, sun " + sun + " ground " + ground + ": by the light's samples " + own + " +- " + ownError +
                                              ", by uniform directions " + uniform + " +- " + uniformError + "; the sphere " + sphere + " +- " + sphereError);
                            if (!sun || elevationDegrees < 0)
                            {
                                EXPECT_LT(Math.Abs(own - uniform), 4 * Math.Sqrt(ownError * ownError + uniformError * uniformError));
                            }
                            // (without a ground no sample is below the horizon: the measure is the hemisphere)
                            EXPECT_LT(Math.Abs(sphere - (ground ? 4 : 2) * Math.PI), 4 * sphereError + 1e-3);
                            EXPECT_LT(ownError, 0.02 * own);
                        }
                    }
                }
            }
        }

        // The solar disc: by the samples of the light, the light of a sky with the sun less that of the sky alone is the
        // radiance of the disc of the model integrated over it
        [TEST("PragueSky", "SolarDisc")]
        public static void SolarDisc()
        {
            string filename = Dataset("PragueSkyModelDatasetSWIR.dat");
            if (filename == null)
            {
                return;
            }
            double elevationDegrees = 35, visibility = 80;
            PragueSkyLight with = Sky(filename, true, false, elevationDegrees, visibility, false, out Vector3f zenith, out Vector3f toSun);
            PragueSkyLight without = Sky(filename, false, false, elevationDegrees, visibility, false, out zenith, out toSun);
            PragueSkyModel model = new PragueSkyModel(filename, elevationDegrees * Math.PI / 180, visibility, new ConstantSpectrum(0.35f));
            LightSampleContext ctx = new LightSampleContext(new Point3fi(new Point3f(0, 0, 0)), new Normal3f(0, 0, 0), new Normal3f(0, 0, 0));
            SampledWavelengths lambda = SampledWavelengths.SampleVisible(0.31f);
            double elevation = elevationDegrees * Math.PI / 180;
            // (the disc is small: its radiance is that of its centre)
            PragueSkyModel.Angles centre = model.ComputeAngles(Math.Cos(elevation), 0, Math.Sin(elevation));
            double expected = model.SunRadiance(centre, lambda[0]) * 2 * Math.PI * (1 - Math.Cos(PragueSkyModel.SunRadius));
            EXPECT_GT(expected, 0);
            RNG rng = new RNG(33);
            int count = 400000;
            double sumWith = 0, sumWithout = 0, squares = 0;
            for (int i = 0; i < count; ++i)
            {
                Point2f u = new Point2f(rng.Uniform<Float>(), rng.Uniform<Float>());
                pstd.optional<LightLiSample> a = with.SampleLi(ctx, u, lambda), b = without.SampleLi(ctx, u, lambda);
                double va = (bool)a ? a.value().L[0] / a.value().pdf : 0, vb = (bool)b ? b.value().L[0] / b.value().pdf : 0;
                sumWith += va;
                sumWithout += vb;
                squares += va * va + vb * vb;
            }
            double difference = (sumWith - sumWithout) / count;
            double error = Math.Sqrt(squares / count / count);
            Console.WriteLine("the disc by the samples " + difference + " +- " + error + ", by the model " + expected);
            EXPECT_LT(Math.Abs(difference - expected), 4 * error + 0.01 * expected);
        }

        // The polarisation of the light is that of the dataset: across the plane of the sun and the direction where the
        // degree is positive, in it where it is negative; none without the option or below the horizon
        [TEST("PragueSky", "LightPolarisation")]
        public static void LightPolarisation()
        {
            string filename = Dataset("PragueSkyModelDatasetSWIR.dat");
            if (filename == null)
            {
                return;
            }
            double elevationDegrees = 12, visibility = 90;
            PragueSkyLight sky = Sky(filename, true, false, elevationDegrees, visibility, true, out Vector3f zenith, out Vector3f toSun);
            PragueSkyLight plain = Sky(filename, true, false, elevationDegrees, visibility, false, out zenith, out toSun);
            PragueSkyModel model = new PragueSkyModel(filename, elevationDegrees * Math.PI / 180, visibility, new ConstantSpectrum(0.35f));
            Vector3f x = Normalize(toSun - Dot(toSun, zenith) * zenith), y = Cross(zenith, x);
            SampledWavelengths lambda = SampledWavelengths.SampleVisible(0.4f);
            SampledSpectrum scalar = new SampledSpectrum(2.0f);
            RNG rng = new RNG(51);
            double most = -1, least = 1;
            int negative = 0;
            for (int i = 0; i < 4000; ++i)
            {
                Vector3f local = SampleUniformHemisphere(new Point2f(rng.Uniform<Float>(), rng.Uniform<Float>()));
                Vector3f toSky = Normalize(local.x * x + local.y * y + local.z * zenith);
                PragueSkyModel.Angles angles = model.ComputeAngles(Dot(toSky, x), Dot(toSky, y), Dot(toSky, zenith));
                if (angles.gamma < 0.02 || Dot(toSky, zenith) < 0.01f)
                {
                    continue;
                }
                double expected = model.Polarisation(angles, lambda[0]);
                most = Math.Max(most, expected);
                least = Math.Min(least, expected);
                negative += expected < 0 ? 1 : 0;
                PolarisedLightSystem.Light found = PolarisedEmission.AtInfinity(sky, -toSky, lambda, scalar);
                Vector3f across = Normalize(Cross(toSky, toSun));
                StokesVector along = found.RepresentInDirection(-toSky, across).ToStokesVector();
                EXPECT_NEAR(2.0, along.s0[0], 1e-5);
                EXPECT_NEAR(2.0 * expected, along.s1[0], 2e-3);
                EXPECT_NEAR(0.0, along.s2[0], 1e-5);
                EXPECT_NEAR(0.0, along.s3[0], 1e-5);
                Interaction point = new Interaction(new Point3f(0, 0, 0), new MediumInterface());
                StokesVector sampled = PolarisedEmission.AtPoint(sky, point, -toSky, lambda, scalar).RepresentInDirection(-toSky, across).ToStokesVector();
                EXPECT_NEAR(2.0 * expected, sampled.s1[0], 2e-3);
                EXPECT_FALSE(PolarisedEmission.AtInfinity(plain, -toSky, lambda, scalar).IsPolarised());
            }
            Console.WriteLine("degree of polarisation at " + lambda[0] + " nm: from " + least + " to " + most + "; negative in " + negative + " directions");
            EXPECT_GT(most, 0.3);
            EXPECT_LT(most, 1.0);
            EXPECT_GT(negative, 0);
            EXPECT_FALSE(PolarisedEmission.AtInfinity(sky, zenith, lambda, scalar).IsPolarised());
        }
    }
